async function customers(){if(busy||pending||blocked||!context?.can_credit||!active()||mode()!=='credit')return;const q=$('#cashier-customer-query').value.trim();clearCustomers();if(q.length>100){status('گەڕان تا ١٠٠ پیت.');return;}const mine=++customerRequest,life=epoch,at=customerOffset;customerLoading=true;controls();try{const data=await KashierData.getCashierCustomers(owner,q,at);if(mine!==customerRequest||life!==epoch||!active()||mode()!=='credit')return;const v=M.customers(data,owner,actor,q,at);customerRows=v.rows;for(const c of v.rows){const option=node('option',c.name+' · '+(c.phone||'بەبێ مۆبایل')+' · '+c.id);option.value=c.id;$('#cashier-customer-id').append(option);}$('#cashier-customer-page').textContent=(at+1)+' · '+v.total;$('#cashier-customer-previous').disabled=at===0;$('#cashier-customer-next').disabled=BigInt(at+v.rows.length)>=BigInt(v.total);status(v.rows.length?'کڕیارەکە بە ناو و مۆبایل پشتڕاست بکەرەوە.':'هیچ کڕیارێک نەدۆزرایەوە.');}catch(e){if(mine===customerRequest&&life===epoch){clearCustomers();if(['staff_access_denied','staff_credit_denied'].includes(e.saleCode)){context=null;$('#cashier-products').replaceChildren();}status(e.message);}}finally{if(mine===customerRequest)customerLoading=false;controls();}}
