$('#cashier-search').addEventListener('submit',e=>{e.preventDefault();offset=0;catalog();});$('#cashier-refresh').addEventListener('click',catalog);$('#cashier-retry').addEventListener('click',send);for(const id of ['discount','received'])$('#cashier-'+id).addEventListener('input',totals);$('#cashier-previous').addEventListener('click',()=>{offset=Math.max(0,offset-50);catalog();});$('#cashier-next').addEventListener('click',()=>{offset+=50;catalog();});$('#cashier-new').addEventListener('click',()=>{if(busy||pending||blocked)return;clearCustomers();$('#cashier-mode').value='cash';paymentView();cart=[];receipt=null;$('#cashier-receipt').hidden=true;for(const id of ['discount','received'])$('#cashier-'+id).value='0';for(const id of ['customer','note'])$('#cashier-'+id).value='';renderCart();});$('#cashier-print').addEventListener('click',()=>{if(receipt&&active())show(receipt.id,true);});
$('#cashier-mode').addEventListener('change',()=>{if(busy||pending||blocked)return;clearCustomers();customerOffset=0;paymentView();controls();if(mode()==='credit')customers();});$('#cashier-customer-search').addEventListener('click',()=>{customerOffset=0;customers();});$('#cashier-customer-query').addEventListener('input',()=>{if(!pending){clearCustomers();controls();}});$('#cashier-customer-id').addEventListener('change',controls);$('#cashier-customer-previous').addEventListener('click',()=>{customerOffset=Math.max(0,customerOffset-50);customers();});$('#cashier-customer-next').addEventListener('click',()=>{customerOffset+=50;customers();});
try{const p=JSON.parse(sessionStorage.getItem(key)||'null');if(p){if(p.version!==1||p.actor!==actor||p.owner!==owner||(p.mode!==undefined&&!['cash','credit'].includes(p.mode)))throw Error();(p.mode==='credit'?M.creditPayload:M.payload)(p.payload,owner);$('#cashier-mode').value=p.mode||'cash';paymentView();pending=p;cart=p.payload.p_items.map(x=>({id:x.product_id,name:'کاڵای داواکاریی پێشوو',price:Number(x.expected_price),quantityUnits:Number(x.quantity_units)}));$('#cashier-discount').value=p.payload.p_discount;$('#cashier-received').value=p.payload.p_received;if(p.mode!=='credit')$('#cashier-customer').value=p.payload.p_customer;else{const option=node('option','کڕیاری داواکاریی پارێزراو · '+p.payload.p_customer);option.value=p.payload.p_customer;$('#cashier-customer-id').append(option);$('#cashier-customer-id').value=p.payload.p_customer;}$('#cashier-note').value=p.payload.p_note;renderCart();}}catch{blocked=true;status('داواکاریی پارێزراو نەخوێندرایەوە؛ پێش فرۆشتنی نوێ لەگەڵ خاوەن پسوولەکان بپشکنە.');}
